  for (let i = 0; i < n; i++) {
    if (a[i] !== b[i]) diffs.push({ i, src: a[i], impl: b[i] });
  }
  console.log(name, "src=", a.length, "impl=", b.length, "identical=", JSON.stringify(a) === JSON.stringify(b));
  for (const d of diffs.slice(0, 20)) console.log("  diff at", d.i, "| src:", JSON.stringify(d.src), "| impl:", JSON.stringify(d.impl));
  if (diffs.length > 20) console.log("  ... and", diffs.length - 20, "more");
  // also check for duplicates within impl
  const dup = b.filter((v, i) => b.indexOf(v) !== i);
  console.log("  duplicates in impl:", dup.length ? dup.length : 0);
}
